function validate([nums1, nums2]) {
  for (const [name, arr] of [['nums1', nums1], ['nums2', nums2]]) {
    if (!Array.isArray(arr) || arr.length < 1 || arr.length > 1000) return `${name} needs 1 to 1000 values.`;
    if (arr.some(v => !Number.isInteger(v) || v < 0 || v > 100)) return `Each value of ${name} is an integer from 0 to 100.`;
  }
  return null;
}

