function findLength(nums1, nums2) {
  let longest = 0;
  // Try every pair of starting points and extend while the values agree.
  for (let a = 0; a < nums1.length; a++) {
    for (let b = 0; b < nums2.length; b++) {
      let len = 0;
      while (a + len < nums1.length && b + len < nums2.length && nums1[a + len] === nums2[b + len]) len++;
      if (len > longest) longest = len;
    }
  }
  return longest;
}

