function generate(rand, size) {
  const large = size === 'large';
  const maxValue = [1, 3, 100][Math.floor(rand() * 3)];
  const make = (len) => Array.from({ length: len }, () => Math.floor(rand() * (maxValue + 1)));
  const nums1 = make(large ? 1000 : 1 + Math.floor(rand() * 10));
  const nums2 = make(large ? 1000 : 1 + Math.floor(rand() * 10));
  // Sometimes copy a block of nums1 into nums2 so a long shared run exists.
  if (rand() < 0.6) {
    const len = 1 + Math.floor(rand() * Math.min(nums1.length, nums2.length));
    const from = Math.floor(rand() * (nums1.length - len + 1));
    const to = Math.floor(rand() * (nums2.length - len + 1));
    for (let t = 0; t < len; t++) nums2[to + t] = nums1[from + t];
  }
  return [nums1, nums2];
}
